// Generates client code from the API's OpenAPI spec so the site, the mod and the API can't drift apart.
//
//   pnpm codegen          write the generated files
//   pnpm codegen:check    exit 1 if any generated file is out of date (also covered by `pnpm test`)
//
// Outputs:
//   api/openapi.json                                      the spec itself (shows API changes in diffs)
//   site/src/api-types.gen.ts                             TypeScript types, via openapi-typescript
//   mod/PassTheWorld/Common/Api/ApiModels.g.cs            C# records, via ./csharp.ts
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';
import { api, openApiConfig } from '../src/app';
import { generateCSharp } from './csharp';

const repoRoot = fileURLToPath(new URL('../../', import.meta.url));

const NOTICE = 'Generated from api/openapi.json by `pnpm codegen`. Do not edit by hand.';

export async function generateFiles(): Promise<Record<string, string>> {
  const doc = api.getOpenAPI31Document(openApiConfig as Parameters<typeof api.getOpenAPI31Document>[0]);
  const schemas = (doc.components?.schemas ?? {}) as Parameters<typeof generateCSharp>[0];

  const ts = astToString(await openapiTS(doc as Parameters<typeof openapiTS>[0]));

  return {
    'api/openapi.json': JSON.stringify(doc, null, 2) + '\n',
    'site/src/api-types.gen.ts': `// ${NOTICE}\n\n${ts}`,
    'mod/PassTheWorld/Common/Api/ApiModels.g.cs': generateCSharp(
      schemas,
      'PassTheWorld.Common.Api',
      `// <auto-generated>\n// ${NOTICE}\n// </auto-generated>`,
    ),
  };
}

/** Paths (relative to the repo root) whose contents differ from what codegen would write. */
export async function staleFiles(): Promise<string[]> {
  const files = await generateFiles();
  return Object.entries(files)
    .filter(([path, content]) => {
      try {
        return readFileSync(repoRoot + path, 'utf8') !== content;
      } catch {
        return true;
      }
    })
    .map(([path]) => path);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  if (process.argv.includes('--check')) {
    const stale = await staleFiles();
    if (stale.length) {
      console.error(`Out of date (run \`pnpm codegen\`):\n  ${stale.join('\n  ')}`);
      process.exit(1);
    }
    console.log('Generated files are up to date.');
  } else {
    for (const [path, content] of Object.entries(await generateFiles())) {
      writeFileSync(repoRoot + path, content);
      console.log(`wrote ${path}`);
    }
  }
}
